//
//  MetadataParserTests.swift
//  WarattilTests
//
//  Phase 2 parity test — BLUEPRINT §10.
//
//  Loads the XML that both platforms bundle, runs the iOS parser, and
//  compares every single (page, juz) boundary against the ground-truth
//  fixture generated by ios/Tools/generate_boundary_fixture.py.
//
//  Expected: 604/604 pages, 30/30 juz, identical startKey and endKey.
//
//  If this test fails after a parser change, DO NOT modify the fixture —
//  the fixture is the Android contract. Fix the parser.
//

import XCTest
@testable import Warattil

final class MetadataParserTests: XCTestCase {

    // In-module parse state is shared across tests; reset before each.
    override func setUp() {
        super.setUp()
        MetadataParser.shared.__resetForTesting()
        do {
            // In the Xcode test target, the XML is copied into the test bundle
            // via Target Membership, so we load it from the test's own bundle.
            try MetadataParser.shared.load(
                bundle: Bundle(for: type(of: self)),
                resourceName: "quran_metadata",
                resourceExtension: "xml"
            )
        } catch {
            XCTFail("Failed to load bundled metadata XML: \(error)")
        }
    }

    // -------------------------------------------------------------------------
    // Basic invariants from BLUEPRINT.
    // -------------------------------------------------------------------------

    func testSuraCount() {
        XCTAssertEqual(MetadataParser.shared.getSuras().count, 114,
                       "Must have exactly 114 suras.")
    }

    func testFirstSuraIsAlFatiha() {
        XCTAssertEqual(MetadataParser.shared.getSuraName(1), "الفاتحة")
    }

    func testLastSuraIsAnNas() {
        XCTAssertEqual(MetadataParser.shared.getSuraName(114), "الناس")
    }

    // -------------------------------------------------------------------------
    // Page boundary parity — the load-bearing test.
    //
    // Reads the JSON fixture generated from the exact same XML by the Python
    // reimplementation of MetadataParser.kt's algorithm. Asserts each of 604
    // page boundaries matches.
    // -------------------------------------------------------------------------

    func testPageBoundariesMatchFixture() throws {
        let fixture = try loadFixture(named: "page_boundaries")
        XCTAssertEqual(fixture.count, 604, "Fixture must have 604 pages.")

        var mismatches: [String] = []
        for entry in fixture {
            let (startKey, endKey) = MetadataParser.shared.getPageBoundaries(entry.index)
            if startKey != entry.startKey || endKey != entry.endKey {
                mismatches.append(
                    "page \(entry.index): expected (\(entry.startKey), \(entry.endKey)) " +
                    "got (\(startKey), \(endKey))"
                )
            }
        }

        XCTAssertTrue(
            mismatches.isEmpty,
            "Page boundary mismatches (\(mismatches.count) of 604):\n" +
            mismatches.prefix(10).joined(separator: "\n") +
            (mismatches.count > 10 ? "\n... (\(mismatches.count - 10) more)" : "")
        )
    }

    func testJuzBoundariesMatchFixture() throws {
        let fixture = try loadFixture(named: "juz_boundaries")
        XCTAssertEqual(fixture.count, 30, "Fixture must have 30 juz.")

        var mismatches: [String] = []
        for entry in fixture {
            let (startKey, endKey) = MetadataParser.shared.getJuzBoundaries(entry.index)
            if startKey != entry.startKey || endKey != entry.endKey {
                mismatches.append(
                    "juz \(entry.index): expected (\(entry.startKey), \(entry.endKey)) " +
                    "got (\(startKey), \(endKey))"
                )
            }
        }

        XCTAssertTrue(
            mismatches.isEmpty,
            "Juz boundary mismatches (\(mismatches.count) of 30):\n" +
            mismatches.joined(separator: "\n")
        )
    }

    // -------------------------------------------------------------------------
    // Spot-checks for pages we've eyeballed manually.
    // -------------------------------------------------------------------------

    func testPage1IsAlFatiha() {
        // Al-Fatiha fills page 1 exactly — 7 ayahs, no overflow.
        let (start, end) = MetadataParser.shared.getPageBoundaries(1)
        XCTAssertEqual(start, 10001)  // 1:1
        XCTAssertEqual(end,   10007)  // 1:7
    }

    func testPage2IsAlBaqarahOpening() {
        // Page 2 is Al-Baqarah 1–5 (5 ayahs).
        let (start, end) = MetadataParser.shared.getPageBoundaries(2)
        XCTAssertEqual(start, 20001)  // 2:1
        XCTAssertEqual(end,   20005)  // 2:5
    }

    func testPage604IsAnNasClosing() {
        // Page 604 ends at An-Nas 6 — the last ayah of the Mushaf.
        let (_, end) = MetadataParser.shared.getPageBoundaries(604)
        XCTAssertEqual(end, 1140006)  // 114:6
    }

    // -------------------------------------------------------------------------
    // Eastern-Arabic-digit helper — invariant per BLUEPRINT §2.3.
    // -------------------------------------------------------------------------

    func testArabicDigits() {
        XCTAssertEqual(0.arabicDigits,   "٠")
        XCTAssertEqual(5.arabicDigits,   "٥")
        XCTAssertEqual(123.arabicDigits, "١٢٣")
        XCTAssertEqual(604.arabicDigits, "٦٠٤")
    }

    // -------------------------------------------------------------------------
    // Share formatter — BLUEPRINT §11.3 is locked.
    // -------------------------------------------------------------------------

    func testAyahShareFormatStripsAnnotations() {
        // U+06E2 = ARABIC SMALL HIGH MEEM ISOLATED FORM (a Quranic annotation).
        let input = "ٱلۡحَمۡدُ لِلَّهِۖ رَبِّ ٱلۡعَٰلَمِينَ\u{06E2}"
        let formatted = ShareUtil.formatAyahForShare(
            text: input,
            surahName: "الفاتحة",
            ayahNumber: 2
        )
        XCTAssertFalse(formatted.contains("\u{06E2}"),
                       "U+06E2 annotation must be stripped")
        XCTAssertTrue(formatted.contains("﴿"),   "Leading ornate bracket present")
        XCTAssertTrue(formatted.contains("﴾"),   "Trailing ornate bracket present")
        XCTAssertTrue(formatted.contains("سورة الفاتحة"), "Surah citation present")
        XCTAssertTrue(formatted.contains("الآية ٢"),      "Ayah number in Eastern digits")
        XCTAssertTrue(formatted.contains("— تطبيق ورتّل"), "Em-dash signature present")
    }

    // =========================================================================
    // Fixture loading helpers
    // =========================================================================

    private struct BoundaryEntry: Decodable {
        let index: Int
        let startSura: Int
        let startAya:  Int
        let startKey:  Int
        let endKey:    Int
    }

    private func loadFixture(named name: String) throws -> [BoundaryEntry] {
        let url = try XCTUnwrap(
            Bundle(for: type(of: self)).url(forResource: name, withExtension: "json"),
            "Fixture \(name).json missing from test bundle. " +
            "Run: python3 ios/Tools/generate_boundary_fixture.py"
        )
        let data = try Data(contentsOf: url)
        return try JSONDecoder().decode([BoundaryEntry].self, from: data)
    }
}
